import hashlib,json,pathlib
P=pathlib.Path(__file__).parent;ROOT=P.parents[3]
# A deterministic boundary counterexample, not measured scheduler timing.
threshold=0.012
ages=[threshold+(rank-3.5)*1e-6 for rank in range(8)]
local=[age>=threshold for age in ages]
assert any(local) and not all(local)
root_decision=local[0]
synchronized=[root_decision]*8
assert len(set(synchronized))==1
fixed_interval=[2>0]*8
assert len(set(fixed_interval))==1
files=['managers/scheduler.py','managers/scheduler_components/request_receiver.py','observability/req_time_stats.py','managers/scheduler_components/batch_result_processor.py','speculative/dflash_worker_v2.py','arg_groups/fields/schedule.py']
report={'status':'AGE_POLICY_HELD_RANK_COHERENCE_AND_MEASUREMENT_REQUIRED','counterexample':{'scope':'Synthetic8-rank timing skew near a generic12ms guard; not observed rank times','threshold_s':threshold,'rank_local_ages_s':ages,'independent_defer_prefill_decisions':local,'root_broadcast_decisions':synchronized,'existing_fixed_interval_decisions':fixed_interval},'source_findings':[{'source':'managers/scheduler.py:2061','finding':'Every scheduler rank runs overlap selection locally after request ingest/broadcast. Selection precedes current forward launch and previous result processing.'},{'source':'managers/scheduler.py:1399','finding':'Existing interval is deterministic countdown; min-batch escape resets it. CPU extracted methods passed158 state tests.'},{'source':'managers/scheduler.py:3972','finding':'Prefill wins whenever admitted, unless interval defers; decode is fallback.'},{'source':'observability/req_time_stats.py:897','finding':'last_decode_finish_time uses host perf_counter at result processing, not CUDA completion. In overlap next forward may already be enqueued.'},{'source':'managers/scheduler.py:4377','finding':'Mixed extend has logprob/embedding/beam/memory guards and joins decode rows as ordinary target EXTEND.'},{'source':'speculative/dflash_worker_v2.py:2345','finding':'EXTEND materializes prompt/aux into draft KV immediately for radix safety; must not delay this to fake overlap.'}], 'admissible_future_design':{'scope':'Generic opt-in prefill admission policy; no workload-specific lengths/concurrency branches','decision':'One designated rank computes age/latency-budget decision, explicitly shared before all ranks select forward mode; or deterministic shared metadata/work-budget proxy with identical calibrated constants.','preserve':['Full requested output and all target/draft context work','KV reservation, cache protection, chunk ownership and overlap WAR ordering','Existing decode-memory checks and finished/inflight request filters','Consistent forward mode/width/collective sequence across TP/EP/DP','Bounded prefill fairness escape and no idle decode admission with no active requests'],'measurement':['Use separate host queue age and asynchronous stream elapsed events; do not relabel host result age as GPU service','No host synchronize to decide each batch','Long nonpreemptive prefill chunks can exceed ITL budget even with one decode between chunks','Any chunk-size or batch-composition change needs complete numerical qualification'],'reason_held':'No actual phase/queue timeline, broadcast cost and numerical batch-shape gate; replay cannot establish throughput gain.'},'replay_verdict':'270 synthetic policy runs conserved prefill tokens, speculative request rounds and width8 verify rows. Additive fixed-work/no-launch cases have identical makespan; launch amortization introduces throughput tradeoffs. No more arbitrary service-curve sweeps needed.','known_replay_limit':'The simple age_guard uses request total prefill age for its fairness escape, which is not an ideal class-starvation metric; its reported numbers are explicitly a toy illustration and do not specify a promoted policy. Real scheduler can co-batch prefills, unlike this replay.','sources':{s:hashlib.sha256((ROOT/'sglang/python/sglang/srt'/s).read_bytes()).hexdigest() for s in files}}
(P/'SCHEDULER_POLICY_FEASIBILITY.json').write_text(json.dumps(report,indent=2))
print(json.dumps(report['counterexample'],indent=2))
